<script>let {entries,media}=$props();const human=s=>s.split('-').map(x=>x.charAt(0).toUpperCase()+x.slice(1)).join(' ');</script>
<ul class="cards">{#each entries as p (p.id)}<li><a href={'/pokemon/'+p.name}><img src={`${media}/media/sprites/pokemon/${p.id}.png`} alt="" loading="lazy"/><span class="number">#{String(p.id).padStart(4,'0')}</span><span>{human(p.name)}</span>{#if p.types}<span class="badges">{#each p.types as t (t)}<span class="badge" style:background={`var(--type-${t})`}>{human(t)}</span>{/each}</span>{/if}{#if p.hidden}<small>Hidden ability</small>{/if}</a></li>{/each}</ul>
